def zeckendorf_length(n):
    if n == 0:
        return 0
    fib = [1, 2]
    while fib[-1] + fib[-2] <= n:
        fib.append(fib[-1] + fib[-2])
    count = 0
    remaining = n
    for f in reversed(fib):
        if f <= remaining:
            remaining -= f
            count += 1
    return count

